export default function Accueil() {
  return (
    <div style={{
      padding: "40px",
      background: "linear-gradient(135deg, #4f46e5, #7c3aed)",
      color: "white",
      borderRadius: "12px",
      margin: "20px"
    }}>
      <h1>Bienvenue sur E-Store</h1>
      <p>Découvrez des milliers de produits</p>

      <Link to="/catalogue">
        <button className="btn" style={{ marginTop: "20px" }}>
          Voir catalogue
        </button>
      </Link>
    </div>
  );
}
